import axios from "axios";
const instance = axios.create({
    baseURL: 'https://social-network.samuraijs.com/api/1.0/',
    withCredentials: true,
    headers: {
        // 'API-KEY': 'c018423f-3c17-4fb9-b3bc-2c484812c346'
        'API-KEY': '64421ba3-c769-433e-85fa-52ac70026508'        

    }

});

export const usersAPI = {
    getUsers(currentPage = 1, pageSize = 10) {
        return instance.get(`users?page=${currentPage}&count=${pageSize}`)
            .then(response => {
                return response.data
            });
    },
    //здесь пропсов нет поєтому ф-я получает єти данные из параметров, пускай передаст тот кото вызывает эту ф-ю
    follow(userId) {
        return instance.post(`https://social-network.samuraijs.com/api/1.0/follow/${userId}`)
    },
    unfollow(userId) {
        return instance.delete(`https://social-network.samuraijs.com/api/1.0/follow/${userId}`)
    }
    // getProfile(userId) {
    //     return instance.get('profile/' + userId )
    //     // console.warn("obslote method please use ProfileAPI");
    //     // return profileAPI.getProfile(userId);
    // }

}
export const profileAPI = {

    getProfile(userId) {
        return instance.get(`profile/` + userId)
        // .then(response => {
        //     return response.data //возвращаем только data
        // });

    },
    getStatus(userId) {
        return instance.get(`profile/status/` + userId)
    },
    updateStatus(status) {
        return instance.put(`profile/status`, { status: status })
    },
    savePhoto(photoFile) {
        const formData = new FormData();
        formData.append("image", photoFile);
        return instance.put(`profile/photo`, formData, {
            headers: {
                'Content-Type': 'multipart/form-data'
            }
        });
    },

    saveProfile(profile) {
        return instance.put(`profile`, profile )
    }

}


export const authAPI = {
    me() {
        return instance.get(`auth/me`)
        // .then(response => {
        //     return response.data
        // });
    },
    login(email, password, rememberMe = false, captcha = null) {
        return instance.post(`auth/login`, { email, password, rememberMe, captcha });

    },
    logout() {
        return instance.delete(`auth/login`);

    }

}


export const securityAPI = {
    getCaptchaUrl() {
        return instance.get(`security/get-captcha-url`)
       
    }

}



