import React from 'react'
import s from './Header.module.css'
import { NavLink } from 'react-router-dom'
import logo from '../../assets/images/logo-reaper-svgrepo-com.svg'

const Header = (props) => {
  return (
    <header className={s.header}>
      <NavLink to={'/profile'} ><img src={logo} alt="" className="" /></NavLink>
      <div className={s.loginBlock}>
        {props.isAuth
          ? <div><span className={s.loginName}>{props.login}</span> - <button className={s.loginBtn} onClick={props.logout}>logout</button></div>
          : <NavLink to={'/login'} ><button className={s.loginBtn}>Login</button></NavLink>}
      </div>
    </header>
  )
}

export default Header